# This is a simple program to compile
extern printf(fmt: string, ...);

frame factorial(n: int) ret int {
    if (n <= 1) {
        return 1;
    }
    return n * factorial(n - 1);
}

frame main() ret int {
    printf("Factorials:\n");

    loop (local i: int = 1; i <= 10; i = i + 1) {
        printf("%d! = %d\n", i, factorial(i));
    }

    return 0;
}

extern printf(fmt: string, ...);

struct Point {
    x: int,
    y: int,
}

frame distance(p1: *Point, p2: *Point) ret int {
    local dx: int = p2.x - p1.x;
    local dy: int = p2.y - p1.y;
    # Simplified: returns dx^2 + dy^2 (no sqrt)
    return dx * dx + dy * dy;
}

frame main() ret int {
    local origin: Point = Point { x: 0, y: 0 };
    local point: Point = Point { x: 3, y: 4 };

    printf("Origin: (%d, %d)\n", origin.x, origin.y);
    printf("Point: (%d, %d)\n", point.x, point.y);

    local distSquared: int = distance(&origin, &point);
    printf("Distance squared: %d\n", distSquared);
    # 3^2 + 4^2 = 9 + 16 = 25

    return 0;
}

