# Bug 1: Off-by-one error
frame buggyLoop() {
    local arr: int[5] = [1, 2, 3, 4, 5];

    # WRONG: i <= 5 goes one past the end!
    # loop (local i = 0; i <= 5; i = i + 1) {

    # CORRECT: i < 5
    loop (local i: int = 0; i < 5; i = i + 1) {
        printf("%d ", arr[i]);
    }
    printf("\n");
}

# Bug 2: Null pointer check
frame safeAccess() {
    local ptr: *int = cast<*int>(malloc(sizeof<int>()));

    # Always check malloc result!
    if (ptr == nullptr) {
        printf("Allocation failed!\n");
        return;
    }

    *ptr = 42;
    printf("Value: %d\n", *ptr);
    free(cast<*void>(ptr));
}

# Bug 3: Integer overflow
frame checkOverflow() {
    local big: int = 2000000000;  # Close to int max
    local result: int = big + big; # Might overflow!
    printf("2B + 2B = %d (overflow!)\n", result);

    # Use larger type if needed
    local big64: i64 = 2000000000;
    local result64: i64 = big64 + big64;
    printf("As i64: %ld\n", result64);
}

frame main() ret int {
    printf("=== Bug Examples ===\n\n");

    printf("1. Array bounds:\n");
    buggyLoop();

    printf("\n2. Null checks:\n");
    safeAccess();

    printf("\n3. Overflow:\n");
    checkOverflow();

    return 0;
}

sections.instructions:
This function has a bug. Find and fix it:

```bpl
frame sumArray(arr: *int, len: int) ret int {
    local sum: int = 0;
    loop (local i: int = 1; i <= len; i = i + 1) {
        sum = sum + *(arr + i);
    }
    return sum;
}
```

It should sum [1,2,3,4,5] = 15, but returns wrong value.

sections.solution:
extern printf(fmt: string, ...);

# Fixed version:
# Bug was: i starts at 1 (skips first element)
#          i <= len (goes past last element)
frame sumArray(arr: *int, len: int) ret int {
    local sum: int = 0;
    loop (local i: int = 0; i < len; i = i + 1) {
        sum = sum + *(arr + i);
    }
    return sum;
}

frame main() ret int {
    local arr: int[5] = [1, 2, 3, 4, 5];
    local result: int = sumArray(&arr[0], 5);
    printf("Sum: %d (should be 15)\n", result);
    return 0;
}
